/** Class statistics over final percentages. */

import { LETTER_BANDS } from "./policy.ts";
import type { StudentResult } from "./types.ts";

/** The arithmetic mean (0 for no values). */
export function mean(values: readonly number[]): number {
  if (values.length === 0) {
    return 0;
  }
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

/** The median (0 for no values). */
export function median(values: readonly number[]): number {
  if (values.length === 0) {
    return 0;
  }
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

/** How many students got each letter, best letter first; letters nobody got are left out. */
export function letterCounts(results: readonly StudentResult[]): Array<[string, number]> {
  const counts: Array<[string, number]> = [];
  for (const [, letter] of LETTER_BANDS) {
    const count = results.filter((result) => result.letter === letter).length;
    if (count > 0) {
      counts.push([letter, count]);
    }
  }
  return counts;
}

/** The plain-text class report. */

import { CATEGORIES } from "./policy.ts";
import { letterCounts, mean, median } from "./stats.ts";
import type { StudentResult } from "./types.ts";

/** Format a percentage with one decimal place, or "-" when it does not count. */
export function formatPercent(value: number | null): string {
  return value === null ? "-" : value.toFixed(1);
}

/** The report: a table with one line per student, then the class summary. */
export function renderReport(results: readonly StudentResult[]): string {
  const header = ["student ", "name".padEnd(16), ...CATEGORIES.map((c) => c.padStart(9))];
  const lines = [[...header, "    final", "  letter"].join("")];
  for (const result of results) {
    const cells = CATEGORIES.map((c) => formatPercent(result.categories[c]).padStart(9));
    lines.push(
      [
        result.student.padEnd(8),
        result.name.padEnd(16),
        ...cells,
        formatPercent(result.percent).padStart(9),
        `  ${result.letter}`,
      ].join(""),
    );
  }
  const finals = results.map((result) => result.percent);
  const letters = letterCounts(results).map(([letter, count]) => `${letter} ${count}`);
  lines.push(
    "",
    `students: ${results.length}`,
    `mean: ${formatPercent(mean(finals))}`,
    `median: ${formatPercent(median(finals))}`,
    `letters: ${letters.join(", ") || "-"}`,
  );
  return `${lines.join("\n")}\n`;
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { letterCounts, mean, median } from "../src/stats.ts";
import type { StudentResult } from "../src/types.ts";

function result(student: string, letter: string): StudentResult {
  const categories = { homework: 0, quizzes: 0, project: 0, exams: 0 };
  return { student, name: student, categories, percent: 0, letter };
}

test("mean of the final percentages", () => {
  assert.equal(mean([80, 90, 100]), 90);
  assert.equal(mean([]), 0);
});

test("median of an odd number of values", () => {
  assert.equal(median([91, 60, 75]), 75);
});

test("median of an even number of values", () => {
  assert.equal(median([60, 70, 80, 90]), 75);
});

test("letter counts list the best letter first and skip letters nobody got", () => {
  const results = [result("s1", "B"), result("s2", "A"), result("s3", "B")];
  assert.deepEqual(letterCounts(results), [
    ["A", 1],
    ["B", 2],
  ]);
});

